package io.github.avinash006.pocketinferencekit.core

import kotlinx.coroutines.flow.Flow

/** A role in the visible chat transcript. */
public enum class ChatRole {
    /** Input supplied by the caller. */
    User,

    /** Output generated by the model. */
    Assistant,
}

/**
 * One immutable entry in a chat transcript.
 *
 * @property role Speaker role.
 * @property text The message body.
 */
public data class ChatMessage(public val role: ChatRole, public val text: String)

/** Chooses the transcript entries to replay before a turn. Shared implementations must be thread-safe. */
public fun interface HistoryTrimmer {
    /** Returns ordered history to retain from a snapshot of committed [history]. */
    public fun trim(history: List<ChatMessage>): List<ChatMessage>

    /** Built-in history policies. */
    public companion object {
        /** Retains up to 16 recent complete user and assistant pairs. */
        public val DropOldest: HistoryTrimmer = HistoryTrimmer { messages ->
            messages.zipWithNext()
                .filter { (user, assistant) -> user.role == ChatRole.User && assistant.role == ChatRole.Assistant }
                .takeLast(16)
                .flatMap { (user, assistant) -> listOf(user, assistant) }
        }
    }
}

/** Thread-safe chat handle. One turn can be active per session. */
public interface ChatSession : AutoCloseable {
    /** Starts a turn with [prompt] each time the cold flow is collected. */
    public fun send(prompt: String): Flow<GenerationEvent>

    /** Streams visible parts of the answer to [prompt] and throws typed SDK failures. */
    public fun sendText(prompt: String): Flow<String>

    /** Collects the visible answer to [prompt] into a single string. */
    public suspend fun sendAndAwait(prompt: String): String

    /** Rejects new turns and requests cancellation of any active turn. */
    override fun close()

    /** Waits for an active turn to release its native conversation. */
    public suspend fun awaitClosed()
}
